<script lang="ts">
 import { untrack,tick } from 'svelte';
 import FormTabs from './FormTabs.svelte';
 import ScheduleRoomPicker from './ScheduleRoomPicker.svelte';
 import { canCheckScheduleAvailability } from '$lib/schedule-availability';
 import { DateTime } from 'luxon';
 import { ambiguousScheduleOffsets,scheduleSubmissionOffset } from '$lib/schedule-offsets';
 import { canOperate,type SessionUser } from '$lib/auth';
 import { localization } from '$lib/localization';
 import { scheduleText } from '$lib/schedule-text';
 import { scheduleRequest,ScheduleRequestError,type ScheduleDraft,type ScheduleItem,type EmployeeChoice } from '$lib/schedule';
 import DetailModal from './DetailModal.svelte';
 import ModalActionButton from './ModalActionButton.svelte';
 import DiscardChangesDialog from './DiscardChangesDialog.svelte';
 import ScheduleDirectory from './ScheduleDirectory.svelte';
 import FormSection from './FormSection.svelte';
 import FormInput from './FormInput.svelte';
 import InfoPopover from './InfoPopover.svelte';
 import FormTextarea from './FormTextarea.svelte';
 import FormCheckbox from './FormCheckbox.svelte';
 import SearchSelect from './SearchSelect.svelte';
 import DatePicker from './DatePicker.svelte';
 let {user,item=null,source=null,initial,onSaved,onClose,returnFocus=null}:{user:SessionUser;item?:ScheduleItem|null;source?:ScheduleItem|null;initial:ScheduleDraft;onSaved:(key:string)=>void|Promise<void>;onClose:()=>void;returnFocus?:HTMLElement|null}=$props();
 let text=$derived(scheduleText[$localization.displayLanguage]);
 let draft=$state<ScheduleDraft>(untrack(()=>structuredClone($state.snapshot(initial))));
 const original=untrack(()=>JSON.stringify(initial)),idempotencyKey=crypto.randomUUID();
 let saving=$state(false),error=$state(''),discard=$state(false),scope=$state<'single'|'following'|'all'>('single'),preserve=$state(true);
 let names=$state<Record<number,string>>(untrack(()=>Object.fromEntries((source??item)?.participants?.map(p=>[p.employeeId,p.name])??[])));
 let roomNames=$state<Record<number,string>>(untrack(()=>Object.fromEntries((source??item)?.resources?.map(r=>[r.id,r.name])??[])));
 let frequency=$state<''|'daily'|'weekly'|'monthly'|'yearly'>(untrack(()=>item?.recurrence?.frequency)??draft.recurrence?.frequency??''),interval=$state<number|undefined>(untrack(()=>item?.recurrence?.interval)??draft.recurrence?.interval??1),count=$state<number|undefined>(untrack(()=>item?.recurrence?.count)??draft.recurrence?.count??10),until=$state(untrack(()=>item?.recurrence?.until)??draft.recurrence?.until??''),repeatEnd=$state<'count'|'until'>(untrack(()=>until)?'until':'count'),weekdays=$state<number[]>(untrack(()=>item?.recurrence?.weekdays)??draft.recurrence?.weekdays??[]),monthDay=$state<number|undefined>(untrack(()=>item?.recurrence?.monthDay)??draft.recurrence?.monthDay??Number(draft.start.slice(8,10)));
 let availability=$state<{affectedCount:number;preservedCount:number;canceledCount:number;employees:{id:number;busy:{start:string;end:string}[]}[];resources:{id:number;busy:{start:string;end:string}[]}[]}|null>(null),checking=$state(false),availabilityError=$state(false),conflictAccepted=$state(false);
 let availabilityRetry=$state(0),availabilityWillRetry=$state(false);
 let releaseFingerprint=$derived.by(()=>{const value=submittedDraft();return JSON.stringify([value.start,value.end,value.allDay,value.timeZone,value.startOffset,value.endOffset,[...value.attendeeIds].sort((a,b)=>a-b),value.resourceIds,value.recurrence,scope,preserve,item?.key,item?.revision]);});
 let openDate=$state(''),dateErrors=$state<Record<string,string>>({});
 let zoneOptions=$derived([...new Set([...Intl.supportedValuesOf('timeZone'),'UTC',draft.timeZone])].sort().map(value=>({value,label:value})));
 let offsetChoices=$derived({start:draft.allDay?[]:ambiguousScheduleOffsets(draft.start,draft.timeZone),end:draft.allDay?[]:ambiguousScheduleOffsets(draft.end,draft.timeZone)});
 function selectedOffset(field:'start'|'end'){const value=draft[field==='start'?'startOffset':'endOffset'];return offsetChoices[field].some(choice=>choice.offset===value)?value:undefined;}
 function changeDate(field:'start'|'end',value:string){if(draft[field]!==value)draft[field==='start'?'startOffset':'endOffset']=undefined;draft[field]=value;dateErrors[field]='';dateErrors[field+'Offset']='';openDate='';}
 function changeZone(value:string){if(draft.timeZone!==value){draft.startOffset=undefined;draft.endOffset=undefined;}draft.timeZone=value;dateErrors.startOffset='';dateErrors.endOffset='';}
 let examples=$derived($localization.displayLanguage==='ja'?{title:'例：開発チーム定例会',location:'例：取引先の東京オフィス',description:'例：議題・事前に確認する事項'}:{title:'Example: Development team meeting',location:'Example: Client office in Tokyo',description:'Example: Agenda and preparation'});
 function validateDates(){dateErrors={};for(const field of ['start','end'] as const){if(!draft[field])dateErrors[field]=text.invalid;if(offsetChoices[field].length&&selectedOffset(field)===undefined)dateErrors[field+'Offset']=text.offset;}if(frequency&&(!item||scope!=='single')&&repeatEnd==='until'&&!until)dateErrors.until=text.invalid;if(draft.start&&draft.end&&draft.end<=draft.start)dateErrors.end=text.invalid;if(frequency&&repeatEnd==='until'&&until&&until<draft.start.slice(0,10))dateErrors.until=text.invalid;const first=Object.keys(dateErrors)[0];if(first){const offset=first==='startOffset'?'start':first==='endOffset'?'end':null;document.querySelector<HTMLButtonElement>(offset?`[aria-controls="schedule-${offset}-offset-options"]`:`[data-field="schedule-${first}"] .date-trigger`)?.focus();}return !first;}
 let checkedFingerprint=$state('');
 const originalRule=untrack(()=>JSON.stringify([frequency,interval,count,until,repeatEnd,weekdays,monthDay]));
 let dirty=$derived(JSON.stringify(draft)!==original||JSON.stringify([frequency,interval,count,until,repeatEnd,weekdays,monthDay])!==originalRule||scope!=='single');
 function close(){if(saving)return;if(dirty)discard=true;else onClose();}
 function submittedDraft():ScheduleDraft {const recurrence:ScheduleDraft['recurrence']=item&&scope==='single'?null:frequency?{frequency,interval:interval??0,...(repeatEnd==='count'?{count:count??0}:{until}),...(frequency==='weekly'&&weekdays.length?{weekdays}:{}),...(frequency==='monthly'?{monthDay:monthDay??0}:{})}:null;return {...draft,startOffset:draft.allDay?undefined:scheduleSubmissionOffset(draft.start,draft.timeZone,draft.startOffset,!!recurrence),endOffset:draft.allDay?undefined:scheduleSubmissionOffset(draft.end,draft.timeZone,draft.endOffset,!!recurrence),attendeeIds:draft.attendeeIds.filter(id=>id!==user.id),recurrence};}
 function allDayChange(value:boolean){draft.allDay=value;draft.startOffset=undefined;draft.endOffset=undefined;draft.start=value?draft.start.slice(0,10):draft.start.slice(0,10)+'T09:00';draft.end=value?DateTime.fromISO(draft.end.slice(0,10)).plus({days:draft.end.slice(0,10)===draft.start.slice(0,10)?1:0}).toISODate()!:draft.end.slice(0,10)+'T10:00';}
 $effect(()=>{
  const fingerprint=releaseFingerprint;void availabilityRetry;
  const input=untrack(()=>{const value=$state.snapshot(submittedDraft());return {...value,title:value.title.trim()||text.create};});
  const eligible=canCheckScheduleAvailability(input);
  availability=null;checkedFingerprint='';availabilityError=false;availabilityWillRetry=false;conflictAccepted=false;checking=eligible;
  if(!eligible)return;
  let disposed=false,controller:AbortController|undefined,timer:ReturnType<typeof setTimeout>,failures=0;
  const request={input,exclude:untrack(()=>item?.key??null),scope:untrack(()=>scope),preserveExceptions:untrack(()=>preserve)};
  async function check(){
   if(disposed)return;checking=true;controller=new AbortController();
   try{const result=await scheduleRequest<NonNullable<typeof availability>>('/v1/schedule-availability','POST',request,{},controller.signal);if(disposed)return;availability=result.data;checkedFingerprint=fingerprint;availabilityError=false;}
   catch(error){if(disposed)return;availability=null;checkedFingerprint='';availabilityError=true;availabilityWillRetry=!(error instanceof ScheduleRequestError)||['NETWORK_ERROR','INTERNAL_ERROR','SERVICE_UNAVAILABLE'].includes(error.code);if(availabilityWillRetry)timer=setTimeout(check,Math.min(15000,5000*++failures));}
   finally{if(!disposed)checking=false;}
  }
  timer=setTimeout(check,350);
  return()=>{disposed=true;clearTimeout(timer);controller?.abort();};
 });
 function revealAvailability(){document.querySelector<HTMLButtonElement>('#schedule-editor [role=tab][data-page-tab=availability]')?.click();void tick().then(()=>document.querySelector<HTMLElement>('#schedule-accept-conflict')?.focus());}

 let roomConflict=$derived(!!availability?.resources.some(r=>r.busy.length)),employeeConflict=$derived(!!availability?.employees.some(e=>e.busy.length));
 async function save(event:SubmitEvent){event.preventDefault();error='';if(!document.querySelector<HTMLFormElement>('#schedule-editor')?.reportValidity()||!validateDates())return;if(checkedFingerprint!==releaseFingerprint||!availability){revealAvailability();return;}if(roomConflict||employeeConflict&&!conflictAccepted){revealAvailability();return;}saving=true;try{const input=submittedDraft();const result=await scheduleRequest<{key:string}>(item?`/v1/schedule-occurrences/${item.key}`:'/v1/schedule-events',item?'PATCH':'POST',item?{input,scope,expectedRevision:item.revision,preserveExceptions:preserve}:input,item?{}:{'idempotency-key':idempotencyKey});await onSaved(result.data.key);onClose();}catch(e){const code=e instanceof ScheduleRequestError?e.code:'';error=code==='ROOM_CONFLICT'?text.roomConflict:code==='STALE_REVISION'?text.conflict:code==='NETWORK_ERROR'?text.failed:text.invalid;if(code==='ROOM_CONFLICT')availabilityRetry++;}finally{saving=false;}}
</script>
<DetailModal title={item?text.edit:text.create} titleId="schedule-editor-title" closeLabel={text.close} {returnFocus} initialFocusSelector="#scheduleTitle" onClose={close}>
 <form data-availability-state={checking?"checking":availabilityError?"error":availability&&checkedFingerprint===releaseFingerprint?roomConflict?"room-conflict":employeeConflict?"employee-conflict":"clear":"waiting"} id="schedule-editor" class="app-modal-form app-modal-form--stacked" onsubmit={save}>
  {#if error}<p class="error" role="alert">{error}</p>{/if}
  <FormTabs label={item?text.edit:text.create} kind="schedule" formId="schedule-editor">
  {#if item?.recurring}<div data-form-panel="scope"><FormSection hideTitle title={text.scope} framed><SearchSelect label={text.scope} field="schedule-scope" value={scope} options={['single','following','all'].map(value=>({value,label:text[value as 'single']}))} disabled={saving} onSelect={value=>{scope=value as typeof scope;if(item?.recurrence?.count)count=scope==='following'?Math.max(1,item.recurrence.count-(item.sequence!-(item.recurrenceFromSequence??0))):item.recurrence.count;}}/>{#if scope!=='single'}<FormCheckbox label={text.preserve} field="schedule-preserve" checked={preserve} disabled={saving} onChange={value=>preserve=value}/><small>{text.exceptions}</small>{/if}<small>{text.confirmScope}</small></FormSection></div>{/if}
  <div data-form-panel="basic"><FormSection hideTitle title={text.title} framed columns={2}>
   <div class="wide"><FormInput label={text.eventTitle} field="scheduleTitle" value={draft.title} placeholder={examples.title} maxlength={255} required disabled={saving} onValueChange={value=>draft.title=value}/></div>
   <div class="wide"><FormCheckbox label={text.allDay} field="schedule-all-day" checked={draft.allDay} disabled={saving} onChange={allDayChange}/></div>
   <DatePicker label={text.start} field="schedule-start" value={draft.start} mode={draft.allDay?'date':'datetime'} required disabled={saving} error={dateErrors.start} open={openDate==='start'} onToggle={()=>openDate=openDate==='start'?'':'start'} onSelect={value=>changeDate('start',value)}/>
   <DatePicker label={text.end} field="schedule-end" value={draft.end} mode={draft.allDay?'date':'datetime'} required disabled={saving} error={dateErrors.end} open={openDate==='end'} onToggle={()=>openDate=openDate==='end'?'':'end'} onSelect={value=>changeDate('end',value)}/>
   <SearchSelect label={text.timeZone} field="schedule-zone" value={draft.timeZone} options={zoneOptions} required disabled={saving} onSelect={changeZone}/>
   <SearchSelect label={text.visibility} field="schedule-visibility" value={draft.visibility} options={[{value:"public",label:text.public},{value:"private",label:text.private}]} disabled={saving} onSelect={value=>draft.visibility=value as typeof draft.visibility}/>
   {#if offsetChoices.start.length||offsetChoices.end.length}<div class="wide offset-fields" role="group" aria-label={text.offset}><p>{text.offset}</p><div class="offsets" class:single-offset={!offsetChoices.start.length||!offsetChoices.end.length}>{#each ['start','end'] as field}{#if offsetChoices[field as 'start'].length}<SearchSelect label={text[field as 'start']} field={`schedule-${field}-offset`} value={String(selectedOffset(field as 'start')??'')} options={[{value:'',label:'-'},...offsetChoices[field as 'start'].map(choice=>({value:String(choice.offset),label:choice.label}))]} searchable={false} required error={dateErrors[field+'Offset']} disabled={saving} onSelect={value=>{draft[field==='start'?'startOffset':'endOffset']=value===''?undefined:Number(value);dateErrors[field+'Offset']='';}}/>{/if}{/each}</div></div>{/if}
   <div class="wide"><FormTextarea label={text.description} field="schedule-description" value={draft.description} placeholder={examples.description} maxlength={10000} rows={4} disabled={saving} onValueChange={value=>draft.description=value}/></div>
  </FormSection></div>
  <div data-form-panel="attendees"><FormSection hideTitle title={text.attendees} framed>
   <div class="chips wide participant-chips">{#each draft.attendeeIds.filter(id=>id!==user.id) as id}<span>{names[id]??id}<button type="button" aria-label={`${text.remove} ${names[id]??id}`} disabled={saving} onclick={()=>draft.attendeeIds=draft.attendeeIds.filter(i=>i!==id)}>×</button></span>{/each}</div>
   <div class="wide participant-picker" ><ScheduleDirectory rowSelection disabled={saving||draft.attendeeIds.length>=200} selected={[user.id,...draft.attendeeIds]} onSelect={item=>{const e=item as EmployeeChoice;if(!saving&&draft.attendeeIds.length<200&&e.id!==user.id&&!draft.attendeeIds.includes(e.id)){draft.attendeeIds=[...draft.attendeeIds,e.id];names[e.id]=e.name;}}}/></div>
  </FormSection></div>
  <div data-form-panel="room"><FormSection hideTitle title={text.location} framed><div class="wide location-field"><div class="location-label"><span aria-hidden="true">{text.location}</span><InfoPopover label={text.locationHelpLabel}><p>{text.locationHelp}</p></InfoPopover></div><FormInput label={text.location} showLabel={false} field="schedule-location" value={draft.location} placeholder={examples.location} maxlength={500} disabled={saving} onValueChange={value=>draft.location=value}/></div><div class="chips wide">{#each draft.resourceIds as id}<span>{roomNames[id]??id}<button type="button" aria-label={text.remove} disabled={saving||!canOperate(user,'schedule.reserve')} onclick={()=>draft.resourceIds=[]}>×</button></span>{:else}<span>{text.none}</span>{/each}</div>{#if canOperate(user,'schedule.reserve')}<div class="wide"><ScheduleRoomPicker value={draft.resourceIds[0]??null} disabled={saving} onSelect={room=>{draft.resourceIds=room?[room.id]:[];if(room)roomNames[room.id]=room.room.name;}}/></div>{/if}</FormSection></div>
  {#if !item||scope!=='single'}<div data-form-panel="repeat"><FormSection hideTitle title={text.repeat} framed columns={2}><SearchSelect label={text.repeat} field="schedule-frequency" value={frequency} options={[{value:"",label:text.never},...["daily","weekly","monthly","yearly"].map(value=>({value,label:text[value as "daily"]}))]} disabled={saving} onSelect={value=>frequency=value as typeof frequency}/>{#if frequency}<FormInput label={text.interval} field="schedule-interval" type="number" value={String(interval??'')} min="1" max="365" placeholder="1" required disabled={saving} onValueChange={value=>interval=value===''?undefined:Number(value)}/>{#if frequency==='weekly'}<div class="wide weekday">{#each [0,1,2,3,4,5,6] as day}<FormCheckbox label={new Intl.DateTimeFormat($localization.displayLanguage,{weekday:"short",timeZone:"UTC"}).format(new Date(Date.UTC(2026,9,25+day)))} field={`schedule-weekday-${day}`} checked={weekdays.includes(day)} disabled={saving} onChange={checked=>weekdays=checked?[...weekdays,day]:weekdays.filter(d=>d!==day)}/>{/each}</div>{/if}{#if frequency==='monthly'}<FormInput label={text.monthDay} field="schedule-monthDay" type="number" value={String(monthDay??'')} min="1" max="31" placeholder="1" required disabled={saving} onValueChange={value=>monthDay=value===''?undefined:Number(value)}/>{/if}<SearchSelect label={text.repeatEnd} field="schedule-repeat-end" value={repeatEnd} options={[{value:"count",label:text.byCount},{value:"until",label:text.byDate}]} disabled={saving} onSelect={value=>repeatEnd=value as typeof repeatEnd}/>{#if repeatEnd==='count'}<FormInput label={text.count} field="schedule-count" type="number" value={String(count??'')} min="1" max="366" placeholder="1" required disabled={saving} onValueChange={value=>count=value===''?undefined:Number(value)}/>{:else}<DatePicker label={text.until} field="schedule-until" value={until} required disabled={saving} error={dateErrors.until} open={openDate==="until"} onToggle={()=>openDate=openDate==="until"?"":"until"} onSelect={value=>{until=value;dateErrors.until="";openDate="";}}/>{/if}{/if}</FormSection></div>{/if}
  <div data-form-panel="availability"><FormSection hideTitle title={text.availability} framed><div class="wide">
   <p class="muted">{text.automaticAvailability}</p>
   {#if checking}<p role="status">{text.checkingAvailability}</p>{:else if availabilityError}<p class="error" role="alert">{availabilityWillRetry?text.availabilityRetrying:text.unknownAvailability}</p>{/if}
   {#if availability&&checkedFingerprint===releaseFingerprint}{#if item?.recurring}<p>{text.scope}: {availability.affectedCount} · {text.preserve}: {availability.preservedCount} · {text.cancellation}: {availability.canceledCount}</p>{/if}{#if roomConflict}<p class="error">{text.roomConflict}</p>{/if}{#if employeeConflict}<p>{text.employeeConflict}</p><FormCheckbox label={text.save} field="schedule-accept-conflict" required checked={conflictAccepted} disabled={saving} onChange={value=>conflictAccepted=value}/>{/if}{#if !roomConflict&&!employeeConflict}<p>{text.availabilityClear}</p>{/if}{#each availability.employees.filter(e=>e.busy.length) as e}<small>{names[e.id]??(e.id===user.id?[user.lastName,user.firstName].join(' '):e.id)}: {e.busy.length}</small>{/each}{/if}
  </div></FormSection></div>
  </FormTabs>
 </form>
 {#snippet actions()}<ModalActionButton label={text.cancel} variant="secondary" disabled={saving} onclick={close}/><ModalActionButton label={saving?text.saving:text.save} type="submit" form="schedule-editor" disabled={saving||checking||availabilityError||roomConflict||!canOperate(user,item?'schedule.update':'schedule.create')}/>{/snippet}
</DetailModal>
{#if discard}<DiscardChangesDialog onContinue={()=>discard=false} onDiscard={onClose}/>{/if}
<style>.participant-chips{min-height:36px}.location-label{display:flex;align-items:center;gap:6px;margin-bottom:6px;font-size:var(--font-size-support);font-weight:500}.participant-picker{height:440px;min-height:0}.participant-picker :global(.directory){display:flex;flex-direction:column;height:100%;min-height:0}.participant-picker :global(.directory>.results){flex:1;min-height:0;max-height:none}.participant-picker :global(.directory>:not(.results)){flex:none}.muted{color:var(--muted);font-size:var(--font-size-support)}.error{color:var(--danger)}.wide{grid-column:1/-1}.offsets{display:grid;grid-template-columns:1fr 1fr;gap:12px}.offsets.single-offset{grid-template-columns:1fr}.offset-fields>p{margin:0 0 8px;font-size:var(--font-size-support);font-weight:500}.chips{display:flex;gap:8px;flex-wrap:wrap}.chips>span{display:flex;gap:8px;align-items:center;padding:4px 8px;background:var(--surface-secondary);border:1px solid var(--border);border-radius:4px}.chips button{padding:0 4px}.weekday{display:flex;gap:12px;flex-wrap:wrap}</style>
